input.command:
powershell.exe -NoProfile -Command '
echo "=== Windows 부팅 시각 / 가동시간 ===";
$os = Get-CimInstance Win32_OperatingSystem;
$os.LastBootUpTime;
"uptime: " + ((Get-Date) - $os.LastBootUpTime).ToString();
echo "";
echo "=== .wslconfig ===";
$w = "C:\Users\dtsli\.wslconfig";
if (Test-Path $w) { Get-Content $w } else { "없음 (기본값: vmIdleTimeout 60초 후 자동 셧다운)" }
echo "";
echo "=== 현재 wsl 관련 프로세스 ===";
Get-Process | Where-Object { $_.Name -match "wsl|vmmem|vmcompute" } | Select-Object Name,Id,StartTime | Format-Table -AutoSize
'

powershell.exe -NoProfile -Command '
echo "=== WSL-Server-Init-Parksy 스케줄 작업 최근 실행 ===";
Get-ScheduledTask -TaskName "*WSL*" -ErrorAction SilentlyContinue | ForEach-Object {
  $i = $_ | Get-ScheduledTaskInfo;
  "{0}  |  Last: {1}  |  Result: 0x{2:X}  |  Next: {3}" -f $_.TaskName, $i.LastRunTime, $i.LastTaskResult, $i.NextRunTime
}
echo "";
echo "=== 16:00~18:00 사이 wsl 관련 이벤트 (Application/System) ===";
Get-WinEvent -FilterHashtable @{LogName="System"; StartTime=(Get-Date "2026-09-08 15:30"); EndTime=(Get-Date "2026-09-08 18:20")} -ErrorAction SilentlyContinue |
  Where-Object { $_.Message -match "WSL|Lxss|Hyper-V|vmcompute|subsystem" } |
  Select-Object TimeCreated, Id, ProviderName, @{n="Msg";e={$_.Message.Substring(0,[Math]::Min(160,$_.Message.Length))}} | Format-List
'

powershell.exe -NoProfile -Command '
echo "=== 깨진 스케줄 작업 액션 경로 ===";
foreach ($t in "WSL-Server-Init-Parksy","WSL_SSHD_Autostart","WSL_Init_Autostart") {
  $st = Get-ScheduledTask -TaskName $t -ErrorAction SilentlyContinue;
  if ($st) {
    "--- $t ---";
    "  Trigger: " + ($st.Triggers | ForEach-Object { $_.CimClass.CimClassName }) ;
    $st.Actions | ForEach-Object { "  Exec: " + $_.Execute + " " + $_.Arguments }
  }
}
echo "";
echo "=== wsl-server-init.sh 파일 존재 확인 ===";
foreach ($p in "D:\PARKSY\dtslib-localpc\wsl-server-init.sh","C:\Users\dtsli\wsl-server-init.sh","D:\PARKSY\termux-archive\wsl-server-init.sh") {
  "{0}  ->  {1}" -f $p, (Test-Path $p)
}
echo "";
echo "=== LxssManager / wsl --shutdown 흔적 (System, 오늘) ===";
Get-WinEvent -FilterHashtable @{LogName="System"; StartTime=(Get-Date "2026-09-08 00:00")} -ErrorAction SilentlyContinue |
  Where-Object { $_.ProviderName -match "Lxss|Wsl" -or $_.Message -match "LxssManager|WSL" } |
  Select-Object TimeCreated, Id, ProviderName, LevelDisplayName, @{n="Msg";e={$_.Message.Substring(0,[Math]::Min(140,$_.Message.Length))}} | Format-List
'

powershell.exe -NoProfile -Command 'wsl -d Ubuntu -u dtsli -- bash -lc "
echo === uptime ===; uptime; cat /proc/uptime;
echo; echo === boots (journalctl) ===; journalctl --list-boots 2>/dev/null | tail -15;
echo; echo === OOM / killed ===; dmesg 2>/dev/null | grep -iE \"out of memory|oom-kill|killed process|Killed\" | tail -20 || echo none;
echo; echo === mem/swap ===; free -h;
echo; echo === prev-boot shutdown reason (journal) ===; journalctl -b -1 -n 15 --no-pager 2>/dev/null || echo no-prev-boot-journal;
"'

powershell.exe -NoProfile -Command '
echo "=== PowerShell 히스토리에서 wsl 종료 흔적 ===";
$h = (Get-PSReadlineOption).HistorySavePath;
if (Test-Path $h) { Select-String -Path $h -Pattern "wsl.*shutdown|wsl.*terminate|Optimize-VHD|wsl --" | Select-Object -Last 15 | ForEach-Object { $_.Line } } else { "히스토리 파일 없음" }
echo "";
echo "=== 오늘 15:00~16:30 실행된 모든 스케줄 작업 ===";
Get-ScheduledTask | ForEach-Object {
  $i = $_ | Get-ScheduledTaskInfo -ErrorAction SilentlyContinue;
  if ($i.LastRunTime -ge (Get-Date "2026-09-08 15:00") -and $i.LastRunTime -le (Get-Date "2026-09-08 16:30")) {
    "{0,-45} Last:{1} Result:0x{2:X}" -f $_.TaskName, $i.LastRunTime, $i.LastTaskResult
  }
}
echo "";
echo "=== .wslconfig / wsl-swap.vhdx 수정 시각 ===";
Get-Item "C:\Users\dtsli\.wslconfig","C:\Users\dtsli\wsl-swap.vhdx" -ErrorAction SilentlyContinue | Select-Object Name, LastWriteTime | Format-Table -AutoSize
echo "=== 오늘 사용자 로그온/잠금해제 이벤트 ===";
Get-WinEvent -FilterHashtable @{LogName="Security"; Id=4624,4801,4802; StartTime=(Get-Date "2026-09-08 15:00")} -ErrorAction SilentlyContinue | Select-Object TimeCreated, Id | Format-Table -AutoSize
'
